# fvs-build-index: full DeepFashion2 → CLIP (+ fine-tuned adapter) → FAISS build on a Kaggle GPU.
#
# GENERATED by ml/kaggle/run_kaggle.py. Edit the template (ml/kaggle/kernel_template.py), not
# the pushed copy. The fvs_ml package is embedded below as a base64 tar.gz so the kernel is
# self-contained: no GitHub clone and no extra dataset upload is needed.
import base64
import io
import json
import logging
import os
import shutil
import subprocess
import sys
import tarfile
import time
from pathlib import Path

BUNDLE = "__BUNDLE__"
SETTINGS = json.loads(r"""__SETTINGS__""")

# Overridable only so the generated kernel can be dry-run locally (see run_kaggle.py dry-run).
WORK = Path(os.environ.get("FVS_KAGGLE_WORK", "/kaggle/working"))
INPUT = Path(os.environ.get("FVS_KAGGLE_INPUT", "/kaggle/input"))
CODE = WORK / "code"
OUT = WORK / "artifacts"
CACHE = WORK / "work"


# 2. Locate the dataset without walking its ~400k files.
def find_dataset_root() -> Path:
    base = INPUT
    for depth in ("*", "*/*", "*/*/*", "*/*/*/*"):
        for p in base.glob(f"{depth}/DeepFashion2"):
            if p.is_dir():
                return p
    return base


def main() -> None:
    t0 = time.time()
    # 1. Unpack the pipeline code and install the two packages Kaggle's image lacks.
    CODE.mkdir(parents=True, exist_ok=True)
    with tarfile.open(fileobj=io.BytesIO(base64.b64decode(BUNDLE)), mode="r:gz") as tf:
        try:
            tf.extractall(CODE, filter="data")
        except TypeError:  # Python < 3.11.4
            tf.extractall(CODE)
    if not os.environ.get("FVS_SKIP_PIP"):
        subprocess.run([sys.executable, "-m", "pip", "install", "-q", "open_clip_torch", "faiss-cpu"], check=True)
    sys.path.insert(0, str(CODE))

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s: %(message)s",
        handlers=[logging.StreamHandler(sys.stdout), logging.FileHandler(WORK / "build.log")],
        force=True,
    )
    log = logging.getLogger("kernel")

    DATASET = find_dataset_root()
    log.info("dataset root: %s", DATASET)

    import torch

    from fvs_ml.config import PipelineConfig
    from fvs_ml.finetune import FinetuneConfig
    from fvs_ml.pipeline import run

    # Don't touch CUDA here: annotation parsing forks/spawns workers first. The pipeline
    # logs the device when it loads CLIP.
    log.info("torch %s", torch.__version__)

    # 3. Build: subset → crops → CLIP → adapter → index → evaluation.
    cfg = PipelineConfig(
        dataset_root=DATASET, output_dir=OUT, work_dir=CACHE,
        target_items=SETTINGS["target_items"], batch_size=SETTINGS["batch_size"],
        num_workers=SETTINGS["num_workers"], io_workers=SETTINGS.get("io_workers", 32), seed=SETTINGS["seed"],
    )
    ft_cfg = FinetuneConfig(epochs=SETTINGS["ft_epochs"], max_items=SETTINGS["ft_max_items"], seed=SETTINGS["seed"])
    compat = CODE / "compatibility.json"
    report = run(cfg, None, compat, skip_eval=False, finetune=SETTINGS["finetune"], ft_cfg=ft_cfg)

    # 4. Package. Thousands of small output files download slowly, so ship a single tar and
    #    delete everything else from /kaggle/working.
    with tarfile.open(WORK / "fvs_artifacts.tar", "w") as tf:
        for name in ("index.faiss", "metadata.json", "manifest.json", "evaluation.json", "adapter.npz", "images"):
            if (OUT / name).exists():
                tf.add(OUT / name, arcname=name)
    summary = {
        "seconds": round(time.time() - t0, 1),
        "catalogue_items": report.get("catalogue_items"),
        "consumer_to_shop": report.get("consumer_to_shop"),
        "variants": report.get("variants"),
        "finetune_chosen_ratio": (report.get("finetune") or {}).get("chosen_ratio"),
        "settings": SETTINGS,
    }
    (WORK / "run_summary.json").write_text(json.dumps(summary, indent=2))
    shutil.copy(OUT / "evaluation.json", WORK / "evaluation.json")
    for d in (OUT, CACHE, CODE):
        shutil.rmtree(d, ignore_errors=True)
    log.info("finished in %.1f min: %s", (time.time() - t0) / 60, json.dumps(summary["consumer_to_shop"]))


# Worker processes (DataLoader / ProcessPool) may re-import this file; only the parent builds.
if __name__ == "__main__":
    main()
